def get_gtf_db(gtf, in_memory=False):
    """
    create a gffutils DB
    """
    if in_memory:
        db = gffutils.create_db(gtf, ':memory:', merge_strategy='create_unique')
    else:
        db = gffutils.create_db(gtf, '.%s.db' % os.path.basename(gtf), merge_strategy='create_unique')
    return db

