def get_gene_transcript_dict(gtf):
    """
    get the gene and transcript dict
    """
    db = get_gtf_db(gtf)
    gene_transcript_dict = {}
    for gene in db.features_of_type('gene'):
        gene_id = gene.id
        gene_transcript_dict[gene_id] = []
        for transcript in db.children(gene, featuretype='transcript', order_by='start'):
            gene_transcript_dict[gene_id].append(transcript.id)
    return gene_transcript_dict


def get_transcript_exon_dict(gtf):
    """
    get the transcript and exon dict
    """
    db = get_gtf_db(gtf)
    transcript_exon_dict = {}
    for transcript in db.features_of_type('transcript'):
        transcript_exon_dict[transcript.id] = []
        for exon in db.children(transcript, featuretype='exon', order_by='start'):
            transcript_exon_dict[transcript.id].append(exon.id)
    return transcript_exon_dict


